for r in RISKS:
    r["i"] = int(r["i"]); r["score"] = r["p"] * r["i"]; r["rating"] = rating(r["score"])
    r["rscore"] = r["rp"] * r["ri"]; r["rrating"] = rating(r["rscore"])

def counts():
    tot = len(RISKS)
    hi = sum(1 for r in RISKS if r["rating"] in ("High", "Critical"))
    rhi = sum(1 for r in RISKS if r["rrating"] in ("High", "Critical"))
    return tot, hi, rhi
